// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateReservationOutputOnly(in *reservationpbv1.Reservation, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "reservations"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLReservationRepository{Svc: b.svc}
	patch := reservationToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "freebusy.reservation.v1/Reservation", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getReservation)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Reservation.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Reservation.Resource.UpdateOp(id, patch, new(resourceql.UpdateReservationResourceByIdResponse)))
		return nil, nil
	})
}

// DeleteReservation queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) DeleteReservation(name string) {
	if _, err := repox.SplitName(name, "reservations"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLReservationRepository{Svc: b.svc}
	queueReservationDelete(b.u, name, true)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Reservation.Resource.DeleteOp(id, new(resourceql.DeleteReservationResourceByIdResponse)))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "freebusy.reservation.v1/Reservation", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getReservation)})
}
